-- Synthetic administrator and validated fixture bundle; every change rolls back.
begin; do $t$ declare u uuid:=gen_random_uuid(); l uuid; result jsonb; begin insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data) values(u,'admin-test-'||u||'@example.invalid','{}','{}'); perform set_config('kineo.internal_update','on',true); update public.profiles set role='admin',study_year=2 where id=u; select id into l from public.lessons limit 1; update public.lessons set validation_status='validated' where id=l; update public.questions set validation_status='validated' where lesson_id=l; perform set_config('request.jwt.claim.sub',u::text,true); execute 'set local role authenticated'; result:=public.get_content_review_queue_v4(); if result is null then raise exception 'No admin queue'; end if; result:=public.publish_lesson_bundle_v1(l); if result is null then raise exception 'No publish result'; end if; execute 'reset role'; end $t$; rollback; select 'admin review and publication passed with a synthetic administrator' as result;
